import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem105 qualifica alegações sem alterar dados operacionais',()=>{for(const [id,titulo,expected,link] of [["mlMLB5386749261","Kit Gamer Teclado E Mouse Led Rgb Usb Para Pc Computador","Kit Gamer Teclado E Mouse Led Rgb Usb Para Pc Computador","https://www.mercadolivre.com.br/up/MLBU5473404077"],["mlMLB5389928608","Pc Computador Cpu Intel I5 10400, Nvme 500gb, 16gb Ram, 500w","PC Intel Core i5-10400 — 16 GB e NVMe de 500 GB anunciados","https://www.mercadolivre.com.br/up/MLBU3175552815?pdp_filters=item_id%3AMLB5389928608"],["mlMLB5408593708","Tênis Casual Kappa Zenit Masculino Unissex Conforto","Tênis casual Kappa Zenit","https://produto.mercadolivre.com.br/MLB-5408593708-tnis-casual-kappa-zenit-masculino-unissex-conforto-_JM?searchVariation=203864180685"]]){const p={id,titulo,link,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.link,p.link);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,id:'outro'}).comentario,p.comentario);}});
